module TopModule (
    input  logic clk,
    input  logic a,
    output logic [2:0] q
);

logic a_d;

always_ff @(posedge clk) begin
    a_d <= a;
    if (a) begin
        q <= 3'd4;
    end else if (!a_d) begin
        case (q)
            3'd4: q <= 3'd5;
            3'd5: q <= 3'd6;
            3'd6: q <= 3'd0;
            3'd0: q <= 3'd1;
            3'd1: q <= 3'd4;
            default: q <= 3'd4;
        endcase
    end
end

endmodule

